// Thứ tự bắt buộc khi chèn vào vị trí K (K > 1):
// 1. Duyệt tmp tới node thứ K - 1
// 2. newNode->next = tmp->next   (nối trước khi đổi tmp->next)
// 3. tmp->next = newNode
//
// Đảo bước 2, 3 sẽ làm mất toàn bộ phần đuôi phía sau vị trí K

void themgiua(node **head, int x, int k){
    int n = len(*head);
    if(k < 1 || k > n + 1){ printf("Khong hop le\n"); return; }
    node *newNode = makeNode(x);
    if(k == 1){ themdau(head, x); return; }
    node *tmp = *head;
    for(int i = 1; i < k - 1; i++) tmp = tmp->next;
    newNode->next = tmp->next;
    tmp->next = newNode;
}

node* themgiua(node *head, int x, int k){
    int n = len(head);
    if(k < 1 || k > n + 1) return head;
    node *newNode = makeNode(x);
    if(k == 1) return themdau(head, x);
    node *tmp = head;
    for(int i = 1; i < k - 1; i++) tmp = tmp->next;
    newNode->next = tmp->next;
    tmp->next = newNode;
    return head;
}

void themgiua(LIST *l, int x, int k){
    int n = len(l->head);
    if(k < 1 || k > n + 1) return;
    node *newNode = makeNode(x);
    if(k == 1){ themdau(l, x); return; }
    node *tmp = l->head;
    for(int i = 1; i < k - 1; i++) tmp = tmp->next;
    newNode->next = tmp->next;
    if(tmp->next == NULL) l->tail = newNode;   // chèn vào cuối
    tmp->next = newNode;
}
